"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { Button } from "./button";
import "./styles/cstrike.css";

interface Server {
  name: string;
  map: string;
  players: number;
  maxPlayers: number;
  ping: number;
  locked?: boolean;
  vac?: boolean;
  game?: string;
}

interface ServerBrowserProps extends React.HTMLAttributes<HTMLDivElement> {
  servers: Server[];
  onConnect?: (server: Server) => void;
  onRefresh?: () => void;
}

type TabKey = "internet" | "favorites" | "history" | "spectate" | "lan";

const TABS: { key: TabKey; label: string }[] = [
  { key: "internet", label: "Internet" },
  { key: "favorites", label: "Favorites" },
  { key: "history", label: "History" },
  { key: "spectate", label: "Spectate" },
  { key: "lan", label: "LAN" },
];

const ServerBrowser = React.forwardRef<HTMLDivElement, ServerBrowserProps>(
  ({ className, servers, onConnect, onRefresh, ...props }, ref) => {
    const [activeTab, setActiveTab] = React.useState<TabKey>("internet");
    const [selectedIndex, setSelectedIndex] = React.useState<number | null>(null);
    const [sortBy, setSortBy] = React.useState<keyof Server>("ping");
    const [sortAsc, setSortAsc] = React.useState(true);

    const sorted = React.useMemo(() => {
      return [...servers].sort((a, b) => {
        const aVal = a[sortBy];
        const bVal = b[sortBy];
        if (typeof aVal === "number" && typeof bVal === "number") {
          return sortAsc ? aVal - bVal : bVal - aVal;
        }
        return sortAsc
          ? String(aVal).localeCompare(String(bVal))
          : String(bVal).localeCompare(String(aVal));
      });
    }, [servers, sortBy, sortAsc]);

    const handleSort = (key: keyof Server) => {
      if (sortBy === key) {
        setSortAsc(!sortAsc);
      } else {
        setSortBy(key);
        setSortAsc(true);
      }
    };

    return (
      <div
        ref={ref}
        className={cn(
          "w-full max-w-3xl bg-[var(--cs-bg)]",
          "border-2 border-t-[var(--cs-border-light)] border-l-[var(--cs-border-light)]",
          "border-b-[var(--cs-border-dark)] border-r-[var(--cs-border-dark)]",
          className
        )}
        {...props}
      >
        {/* Title bar */}
        <div className="flex items-center justify-between px-3 py-1.5 bg-[var(--cs-bg-secondary)] border-b-2 border-b-[var(--cs-border-dark)]">
          <span className="cs-font-ui text-sm text-[var(--cs-text-title)] cs-text-shadow">
            Server Browser
          </span>
          <button className="cs-font-ui text-xs text-[var(--cs-text-dim)] hover:text-white">
            ✕
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b-2 border-b-[var(--cs-border-dark)] bg-[var(--cs-bg-secondary)]">
          {TABS.map((tab) => (
            <button
              key={tab.key}
              className={cn(
                "cs-font-ui text-xs px-4 py-1.5 border-r border-r-[var(--cs-border-dark)]",
                "transition-none",
                activeTab === tab.key
                  ? "bg-[var(--cs-bg)] text-[var(--cs-text-bright)] border-b-0"
                  : "bg-[var(--cs-bg-secondary)] text-[var(--cs-text-dim)] hover:text-[var(--cs-text)]"
              )}
              onClick={() => setActiveTab(tab.key)}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* Server list */}
        <div className="overflow-auto max-h-80">
          <table className="w-full border-collapse">
            <thead className="sticky top-0">
              <tr className="bg-[var(--cs-bg-secondary)]">
                <th className="w-6 px-1 py-1" />
                <th className="w-6 px-1 py-1" />
                <th
                  className="px-2 py-1 text-left cs-font-ui text-[10px] text-[var(--cs-text-secondary)] uppercase cursor-pointer hover:text-[var(--cs-text-bright)]"
                  onClick={() => handleSort("name")}
                >
                  Server Name {sortBy === "name" && (sortAsc ? "▲" : "▼")}
                </th>
                <th
                  className="px-2 py-1 text-left cs-font-ui text-[10px] text-[var(--cs-text-secondary)] uppercase cursor-pointer hover:text-[var(--cs-text-bright)] w-24"
                  onClick={() => handleSort("map")}
                >
                  Map {sortBy === "map" && (sortAsc ? "▲" : "▼")}
                </th>
                <th
                  className="px-2 py-1 text-center cs-font-ui text-[10px] text-[var(--cs-text-secondary)] uppercase cursor-pointer hover:text-[var(--cs-text-bright)] w-20"
                  onClick={() => handleSort("players")}
                >
                  Players {sortBy === "players" && (sortAsc ? "▲" : "▼")}
                </th>
                <th
                  className="px-2 py-1 text-center cs-font-ui text-[10px] text-[var(--cs-text-secondary)] uppercase cursor-pointer hover:text-[var(--cs-text-bright)] w-16"
                  onClick={() => handleSort("ping")}
                >
                  Ping {sortBy === "ping" && (sortAsc ? "▲" : "▼")}
                </th>
              </tr>
            </thead>
            <tbody>
              {sorted.map((server, i) => (
                <tr
                  key={i}
                  className={cn(
                    "border-b border-b-[#1a1a1a] cursor-pointer",
                    selectedIndex === i
                      ? "bg-[var(--cs-bg-selection)]"
                      : i % 2 === 0
                      ? "bg-[var(--cs-bg-darkest)]"
                      : "bg-[var(--cs-bg-darker)]",
                    "hover:bg-[var(--cs-bg-selection)]"
                  )}
                  onClick={() => setSelectedIndex(i)}
                  onDoubleClick={() => onConnect?.(server)}
                >
                  <td className="px-1 py-0.5 text-center text-xs">
                    {server.locked && (
                      <span className="text-[var(--cs-accent)]" title="Password Protected">
                        🔒
                      </span>
                    )}
                  </td>
                  <td className="px-1 py-0.5 text-center text-xs">
                    {server.vac && (
                      <span className="text-[var(--cs-hud-green)]" title="VAC Secured">
                        ✓
                      </span>
                    )}
                  </td>
                  <td className="px-2 py-0.5 cs-font-ui text-xs text-[var(--cs-text)] truncate max-w-[200px]">
                    {server.name}
                  </td>
                  <td className="px-2 py-0.5 cs-font-ui text-xs text-[var(--cs-text-secondary)]">
                    {server.map}
                  </td>
                  <td className="px-2 py-0.5 text-center cs-font-ui text-xs text-[var(--cs-text)]">
                    {server.players}/{server.maxPlayers}
                  </td>
                  <td
                    className={cn(
                      "px-2 py-0.5 text-center cs-font-ui text-xs",
                      server.ping < 50
                        ? "text-[var(--cs-hud-green)]"
                        : server.ping < 100
                        ? "text-[var(--cs-hud-amber)]"
                        : "text-[var(--cs-hud-red)]"
                    )}
                  >
                    {server.ping}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Bottom bar */}
        <div className="flex items-center justify-between px-3 py-2 bg-[var(--cs-bg-secondary)] border-t-2 border-t-[var(--cs-border-dark)]">
          <span className="cs-font-ui text-[10px] text-[var(--cs-text-dim)]">
            {servers.length} servers
          </span>
          <div className="flex items-center gap-2">
            <Button variant="default" size="sm" onClick={onRefresh}>
              Refresh
            </Button>
            <Button
              variant="default"
              size="sm"
              disabled={selectedIndex === null}
              onClick={() =>
                selectedIndex !== null && onConnect?.(sorted[selectedIndex])
              }
            >
              Connect
            </Button>
          </div>
        </div>
      </div>
    );
  }
);
ServerBrowser.displayName = "ServerBrowser";

export { ServerBrowser, type Server, type ServerBrowserProps };

"use client";

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import "./styles/cstrike.css";

const buttonVariants = cva(
  [
    "cs-font-ui cs-text-shadow inline-flex items-center justify-center",
    "cursor-pointer select-none whitespace-nowrap",
    "transition-none",
    "disabled:pointer-events-none disabled:opacity-50",
  ].join(" "),
  {
    variants: {
      variant: {
        default: [
          "bg-[var(--cs-bg)] text-[var(--cs-text-control)]",
          "border-2 border-t-[var(--cs-border-light)] border-l-[var(--cs-border-light)]",
          "border-b-[var(--cs-border-dark)] border-r-[var(--cs-border-dark)]",
          "hover:text-[var(--cs-text-menu-hover)]",
          "active:border-t-[var(--cs-border-dark)] active:border-l-[var(--cs-border-dark)]",
          "active:border-b-[var(--cs-border-light)] active:border-r-[var(--cs-border-light)]",
          "active:text-[var(--cs-text-menu-active)]",
        ].join(" "),
        menu: [
          "bg-transparent text-[var(--cs-text-menu)] border-none",
          "hover:text-[var(--cs-text-menu-hover)]",
          "active:text-[var(--cs-text-menu-active)]",
          "justify-start",
        ].join(" "),
        buy: [
          "bg-[var(--cs-bg-secondary)] text-[var(--cs-text-control)]",
          "border-2 border-t-[var(--cs-border-light)] border-l-[var(--cs-border-light)]",
          "border-b-[var(--cs-border-dark)] border-r-[var(--cs-border-dark)]",
          "hover:bg-[var(--cs-bg)] hover:text-[var(--cs-text-bright)]",
          "active:border-t-[var(--cs-border-dark)] active:border-l-[var(--cs-border-dark)]",
          "active:border-b-[var(--cs-border-light)] active:border-r-[var(--cs-border-light)]",
        ].join(" "),
        hud: [
          "bg-transparent text-[var(--cs-hud-amber)] border-none",
          "cs-hud-glow",
          "hover:brightness-125",
          "active:brightness-75",
        ].join(" "),
        destructive: [
          "bg-[#3a1a1a] text-[var(--cs-team-t)]",
          "border-2 border-t-[#663333] border-l-[#663333]",
          "border-b-[#1a0a0a] border-r-[#1a0a0a]",
          "hover:text-white",
          "active:border-t-[#1a0a0a] active:border-l-[#1a0a0a]",
          "active:border-b-[#663333] active:border-r-[#663333]",
        ].join(" "),
      },
      size: {
        default: "h-9 px-4 py-2 text-sm",
        sm: "h-7 px-3 py-1 text-xs",
        lg: "h-11 px-6 py-3 text-base",
        icon: "h-9 w-9 p-0",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return (
      <Comp
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    );
  }
);
Button.displayName = "Button";

export { Button, buttonVariants };

/* Counter-Strike 1.6 Design System */

/* CS 1.6 Logo Font - "Counter-Strike" by SoJa (free, public domain) */
@font-face {
  font-family: "Counter-Strike";
  src: url("/fonts/counter-strike.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

/* ===== CS 1.6 VGUI Color System ===== */
:root {
  /* Primary olive-green backgrounds */
  --cs-bg: #4a5942;
  --cs-bg-secondary: #3e4637;
  --cs-bg-dark: #333433;
  --cs-bg-darker: #292929;
  --cs-bg-darkest: #1a1a1a;
  --cs-bg-control: #1a1a1a;
  --cs-bg-selection: #282e22;
  --cs-bg-list: #292929;

  /* Text colors */
  --cs-text: #dedfd6;
  --cs-text-secondary: #a0aa95;
  --cs-text-dim: #75806f;
  --cs-text-disabled: #282e22;
  --cs-text-control: #fffac1;
  --cs-text-bright: #ffc000;
  --cs-text-title: #ffde00;
  --cs-text-menu: #ffcc00;
  --cs-text-menu-hover: #ffffff;
  --cs-text-menu-active: #c0ba50;

  /* Accent colors */
  --cs-accent: #c4b550;
  --cs-accent-secondary: #958831;

  /* Border colors (3D bevel system) */
  --cs-border-light: #8c9284;
  --cs-border-dark: #292c21;
  --cs-border-outline: #000000;

  /* HUD colors (from GoldSrc engine hud.h) */
  --cs-hud-amber: #ffa000;
  --cs-hud-red: #ff1010;
  --cs-hud-green: #00a000;

  /* Team colors */
  --cs-team-ct: #99ccff;
  --cs-team-t: #ff4040;
  --cs-team-neutral: #cccccc;

  /* Slider/scrollbar */
  --cs-slider: #7f8c7f;
  --cs-slider-bg: #1f1f1f;
  --cs-scrollbar-track: #5a6a50;
}

/* ===== Font Classes ===== */
.cs-font-logo {
  font-family: "Counter-Strike", "Impact", sans-serif;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.cs-font-ui {
  font-family: "Verdana", "DejaVu Sans", system-ui, sans-serif;
  font-weight: 600;
  line-height: 1.5;
}

.cs-font-hud {
  font-family: "Courier New", "Courier", monospace;
  font-weight: 700;
  letter-spacing: 1px;
}

.cs-font-console {
  font-family: "Tahoma", "Geneva", sans-serif;
  font-size: 13px;
  line-height: 1.4;
}

/* ===== 3D Beveled Borders ===== */
.cs-bevel-raised {
  border-width: 2px;
  border-style: solid;
  border-top-color: var(--cs-border-light);
  border-left-color: var(--cs-border-light);
  border-bottom-color: var(--cs-border-dark);
  border-right-color: var(--cs-border-dark);
}

.cs-bevel-inset {
  border-width: 2px;
  border-style: solid;
  border-top-color: var(--cs-border-dark);
  border-left-color: var(--cs-border-dark);
  border-bottom-color: var(--cs-border-light);
  border-right-color: var(--cs-border-light);
}

/* ===== HUD Glow Effect ===== */
.cs-hud-glow {
  color: var(--cs-hud-amber);
  text-shadow:
    0 0 8px rgba(255, 160, 0, 0.6),
    0 0 16px rgba(255, 160, 0, 0.3);
}

.cs-hud-glow-red {
  color: var(--cs-hud-red);
  text-shadow:
    0 0 8px rgba(255, 16, 16, 0.6),
    0 0 16px rgba(255, 16, 16, 0.3);
}

.cs-hud-glow-green {
  color: var(--cs-hud-green);
  text-shadow:
    0 0 8px rgba(0, 160, 0, 0.6),
    0 0 16px rgba(0, 160, 0, 0.3);
}

/* ===== Text Shadow (VGUI style) ===== */
.cs-text-shadow {
  text-shadow: 1px 1px 0px rgba(0, 0, 0, 0.8);
}

/* ===== Panel Backgrounds ===== */
.cs-panel {
  background-color: var(--cs-bg);
}

.cs-panel-dark {
  background-color: var(--cs-bg-dark);
}

.cs-panel-control {
  background-color: var(--cs-bg-control);
}
